"""Only make files generated by this app downloadable, not arbitrary Downloads files."""
import hashlib
import json
import os
from tempfile import NamedTemporaryFile
from pathlib import Path
from urllib.parse import quote
from ..config import DATA, EXPORTS, EXPORT_ROOTS

def record_path(filename: str) -> Path:
    return DATA / 'export-records' / (hashlib.sha256(filename.encode('utf-8')).hexdigest() + '.json')

def register(target: Path, sha256: str | None = None) -> str:
    custom = target.resolve().parent != EXPORTS.resolve()
    filename = (hashlib.sha256(str(target.resolve()).encode('utf-8')).hexdigest() + '__' + target.name) if custom else target.name
    record = record_path(filename)
    record.parent.mkdir(parents=True, exist_ok=True)
    temp=None
    try:
        with NamedTemporaryFile(mode='w',encoding='utf-8',dir=record.parent,prefix='.record-',delete=False) as stream:
            temp=Path(stream.name)
            json.dump({'file_path':str(target.resolve()),'custom':custom,**({'sha256':sha256} if sha256 else {})},stream,ensure_ascii=False)
            stream.flush();os.fsync(stream.fileno())
        temp.replace(record)
    finally:
        if temp is not None:temp.unlink(missing_ok=True)
    return '/api/exports/' + quote(filename, safe='')

def lookup(filename: str) -> Path | None:
    if Path(filename).name != filename:
        return None
    record = record_path(filename)
    if record.is_file():
        try:
            metadata = json.loads(record.read_text('utf-8'))
            target = Path(metadata['file_path']).resolve()
        except (OSError,ValueError,KeyError,TypeError):return None
        if metadata.get('sha256'):
            if not target.is_file():return None
            digest=hashlib.sha256()
            with target.open('rb') as stream:
                for block in iter(lambda:stream.read(1024*1024),b''):digest.update(block)
            if digest.hexdigest()!=metadata['sha256']:return None
        if metadata.get('custom') and filename == hashlib.sha256(str(target).encode('utf-8')).hexdigest() + '__' + target.name and target.is_file():
            return target
        alias=metadata.get('migration_alias')
        if (metadata.get('custom') and metadata.get('sha256') and isinstance(alias,dict)
                and alias.get('version')==1 and isinstance(alias.get('previous_path'),str)
                and target.is_relative_to((DATA/'exports').resolve()) and target.is_file()):
            previous=Path(alias['previous_path'])
            if previous.is_absolute() and previous.name==target.name and filename==hashlib.sha256(str(previous).encode('utf-8')).hexdigest()+'__'+target.name:
                return target
        if target.parent in {EXPORTS.resolve(), *EXPORT_ROOTS} and target.name == filename and target.is_file():
            return target
    # Keep pre-existing exports and database backups downloadable from the private library.
    target = (DATA / 'exports' / filename).resolve()
    if target.parent == (DATA / 'exports').resolve() and target.is_file():
        return target
    return None

def registered_files() -> set[Path]:
    """Exclude generated files even when users export into a scanned source folder."""
    result: set[Path] = set()
    for record in (DATA / 'export-records').glob('*.json'):
        try:
            result.add(Path(json.loads(record.read_text('utf-8'))['file_path']).resolve())
        except (OSError, ValueError, KeyError):
            continue
    return result
